#include "s61_binary_deeper_quartic_field_20261101.hpp"
#include <chrono>
int main(int argc,char**argv){assert(argc==6);fmpq_mpoly_ctx_init(ctx,2,ORD_LEX);{ifstream bin(argv[1]),in(argv[2]);int nb,nc;bin>>nb>>nc;assert(nb==48 && nc==84);vector<Row>B(nb);vector<int>piv(nb);for(int i=0;i<nb;i++){int n;bin>>piv[i]>>n;for(int k=0;k<n;k++){int j;bin>>j;readpoly(bin,B[i][j].n);readpoly(bin,B[i][j].d);}}int nr,ncol;in>>nr>>ncol;assert(ncol==nc);vector<Row>A(2);for(int i=0;i<nr;i++){int n;in>>n;for(int k=0;k<n;k++){int j;in>>j;Rat x;readpoly(in,x.n);readpoly(in,x.d);if(i==51)A[0][j]=x;if(i==55)A[1][j]=std::move(x);}}ofstream out(argv[3]),dual(string(argv[3])+".dual");out<<"2 2\n";dual<<"2 "<<nc<<'\n';vector<vector<Rat>>M(2,vector<Rat>(2));auto start=chrono::steady_clock::now();for(int v=0;v<2;v++){int column=stoi(argv[4+v]);for(int p:piv)assert(column!=p);Row lambda;fmpq_mpoly_one(lambda[column].n,ctx);for(int i=nb-1;i>=0;i--){Rat value;for(auto&[j,c]:B[i]){auto it=lambda.find(j);if(it==lambda.end())continue;value=sub(value,mul(c,it->second));}if(!value.zero())lambda[piv[i]]=std::move(value);cerr<<"DUAL "<<column<<" step "<<i<<" seconds "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';}dual<<column<<' '<<lambda.size()<<'\n';for(auto&[j,c]:lambda){dual<<j<<'\n';writepoly(dual,c.n);writepoly(dual,c.d);}dual.flush();for(int a=0;a<2;a++){Rat value;for(auto&[j,c]:A[a]){auto it=lambda.find(j);if(it==lambda.end())continue;value=sub(value,mul(c,it->second));}fmpq_mpoly_neg(value.n,value.n,ctx);M[a][v]=value;out<<a<<' '<<v<<'\n';writepoly(out,value.n);writepoly(out,value.d);out.flush();cerr<<"VALUE "<<a<<' '<<v<<" terms "<<fmpq_mpoly_length(value.n,ctx)<<' '<<fmpq_mpoly_length(value.d,ctx)<<" seconds "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';}}
Rat det=sub(mul(M[0][0],M[1][1]),mul(M[0][1],M[1][0]));assert(!det.zero());out<<"DETERMINANT\n";writepoly(out,det.n);writepoly(out,det.d);cerr<<"DUAL MINOR PASS "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
